# 12_tables.R: summary tables for Simulations A and B (no refitting). Across the 50 replicates (independent simulations): median, central 95% interval (2.5/97.5% quantiles), number of replicates with positive paired gain,
# two-sided Wilcoxon signed-rank and sign-test p-values (descriptive; replicates are independent draws but no multiplicity correction is applied). Nothing is selected on predictive gain. Run from final/.
suppressMessages({library(dplyr); library(tidyr)}); OUT <- "revision_sim/tables"; q <- function(x, p) unname(quantile(x, p, type = 7, na.rm = TRUE)); wp <- function(x) if (sum(is.finite(x) & x != 0) < 5) NA_real_ else suppressWarnings(wilcox.test(x, mu = 0)$p.value); sp <- function(x) { x <- x[is.finite(x) & x != 0]; if (length(x) < 5) NA_real_ else binom.test(sum(x > 0), length(x))$p.value }
sm <- function(x) c(median = median(x, na.rm = TRUE), q025 = q(x, .025), q975 = q(x, .975), mean = mean(x, na.rm = TRUE), n = sum(is.finite(x)))
gains <- function(M, grp) { W <- M |> select(all_of(grp), replicate, config, D2_test) |> pivot_wider(names_from = config, values_from = c(D2_test)); cfg <- c("interaction_5e-03", "interaction_1e-04", "interaction_1e-06")
  bind_rows(lapply(c(paste0(cfg, " minus additive"), "additive minus spread_only", "interaction_1e-06 minus spread_only"), function(nm) { a <- strsplit(nm, " minus ")[[1]]; d <- W |> mutate(gain = .data[[a[1]]] - .data[[a[2]]]) |> group_by(across(all_of(grp))) |> summarise(median = median(gain), q025 = q(gain, .025), q975 = q(gain, .975), mean = mean(gain), n_replicates = n(), n_positive = sum(gain > 0), wilcoxon_p = wp(gain), sign_test_p = sp(gain), .groups = "drop"); d$contrast <- nm; d })) }
perf <- function(M, grp) M |> group_by(across(all_of(c(grp, "config")))) |> summarise(D2_test_median = median(D2_test), D2_test_q025 = q(D2_test, .025), D2_test_q975 = q(D2_test, .975), D2_train_median = median(D2_train), oracle_D2_median = if ("oracle_D2_test" %in% names(M)) median(oracle_D2_test) else NA_real_, n_converged = sum(converged), n_fits = n(), .groups = "drop")
surf <- function(M, grp) M |> group_by(across(all_of(c(grp, "config")))) |> summarise(rmse_link_median = median(rmse_link, na.rm = TRUE), rmse_resp_median = median(rmse_resp, na.rm = TRUE), cor_link_median = median(cor_link, na.rm = TRUE), cor_resp_median = median(cor_resp, na.rm = TRUE), n_supported_cells_median = median(n_supported_cells), prop_matched_support = mean(matched_support), .groups = "drop")
contr <- function(M, grp) M |> filter(matched_support) |> group_by(across(all_of(c(grp, "config")))) |> summarise(n_matched = n(), true_link_did = median(true_link_did), est_link_did = median(est_link_did), bias_link_did = median(est_link_did - true_link_did), true_resp_did = median(true_resp_did), est_resp_did = median(est_resp_did), bias_resp_did = median(est_resp_did - true_resp_did),
  true_link_did_explicit = median(true_link_did_explicit), est_link_did_explicit = median(est_link_did_explicit), q025_est_link_did_explicit = q(est_link_did_explicit, .025), q975_est_link_did_explicit = q(est_link_did_explicit, .975), true_resp_did_explicit = median(true_resp_did_explicit), est_resp_did_explicit = median(est_resp_did_explicit), .groups = "drop")
for (suf in c("", "_T1000")) { f <- sprintf("%s/simA_metrics%s.csv", OUT, suf); if (!file.exists(f)) next; M <- read.csv(f); g <- c("scenario", "order"); write.csv(gains(M, g), sprintf("%s/simA_summary_gains%s.csv", OUT, suf), row.names = FALSE); write.csv(perf(M, g), sprintf("%s/simA_summary_performance%s.csv", OUT, suf), row.names = FALSE); write.csv(surf(M, g), sprintf("%s/simA_summary_surface%s.csv", OUT, suf), row.names = FALSE); write.csv(contr(M, g), sprintf("%s/simA_summary_contrasts%s.csv", OUT, suf), row.names = FALSE)
  C <- read.csv(sprintf("%s/simA_coefficients%s.csv", OUT, suf)); R <- C |> group_by(scenario, order, config, term) |> summarise(truth = unique(truth), median = median(estimate), q025 = q(estimate, .025), q975 = q(estimate, .975), bias = mean(estimate - truth), rmse = sqrt(mean((estimate - truth)^2)), mean_estimate = mean(estimate), n = n(), n_nonconverged = sum(!converged), .groups = "drop"); write.csv(R, sprintf("%s/simA_summary_coefficient_recovery%s.csv", OUT, suf), row.names = FALSE) }
M <- read.csv(file.path(OUT, "simB_metrics.csv")); g <- c("scenario", "response", "order"); write.csv(gains(M, g), file.path(OUT, "simB_summary_gains.csv"), row.names = FALSE); write.csv(perf(M, g), file.path(OUT, "simB_summary_performance.csv"), row.names = FALSE); write.csv(surf(M, g), file.path(OUT, "simB_summary_surface.csv"), row.names = FALSE)
write.csv(contr(M |> mutate(true_link_did_explicit = NA_real_, true_resp_did_explicit = NA_real_), g), file.path(OUT, "simB_summary_contrasts.csv"), row.names = FALSE)
info <- M |> filter(config == "additive", response == "relative") |> group_by(scenario, order) |> summarise(sharing_probability_median = median(sharing_probability), prop_sharing_ge_0.10 = mean(sharing_probability >= .10), prop_matched_support = mean(matched_support), n_supported_cells_median = median(n_supported_cells), n_train_sets_median = median(n_train_sets), n_replicates = n(), .groups = "drop"); write.csv(info, file.path(OUT, "simB_order_information.csv"), row.names = FALSE)
cv <- bind_rows(M |> mutate(sim = "B") |> select(sim, config, converged), read.csv(file.path(OUT, "simA_metrics.csv")) |> mutate(sim = "A") |> select(sim, config, converged)) |> group_by(sim, config) |> summarise(n_fits = n(), n_nonconverged = sum(!converged), .groups = "drop"); write.csv(cv, file.path(OUT, "sim_convergence.csv"), row.names = FALSE); print(cv)
options(width = 220, digits = 3); gA <- read.csv(file.path(OUT, "simA_summary_gains.csv")); print(gA |> filter(contrast == "interaction_1e-06 minus additive") |> select(scenario, order, median, q025, q975, n_positive, wilcoxon_p) |> as.data.frame())
